var RULES = [["Concepte", "Unități și modele", "01.02 · p.8", "O unitate poate conține unul sau mai multe modele. Când o regulă afectează o unitate, efectul se aplică fiecărui model din acea unitate. Friendly înseamnă din armata ta; enemy înseamnă din armata adversă.", "O regulă care spune «unitatea» se aplică tuturor modelelor ei."], ["Concepte", "Măsurarea distanțelor", "01.04 · p.9", "Distanțele sunt măsurate în inch. Dacă o regulă nu spune altceva, măsoară până la sau de la cea mai apropiată parte a bazei modelului.", "Poți măsura distanțe oricând."], ["Concepte", "Leadership și Battle-shock", "01.06–01.07 · p.9", "Leadership roll: arunci 2D6; rezultatul trebuie să fie egal sau mai mare decât una sau mai multe caracteristici Ld din unitate. Un Battle-shock roll reușit evită sau înlătură Battle-shock; unul eșuat aplică starea.", "Cât timp este Battle-shocked: OC devine «-», unitatea nu poate fi țintită de stratageme de către propriul jucător și nu poate începe ori finaliza Actions."], ["Datasheets", "Caracteristici și arme", "02.02–02.05 · p.10", "Datasheet-ul descrie Move, Toughness, Save, Invulnerable Save, Wounds, Leadership și Objective Control. Armele au Range, Attacks, BS/WS, Strength, AP și Damage.", "OC «-» înseamnă că modelul nu poate controla obiective."], ["Movement", "Principii de mișcare", "03.01 · p.12–13", "La o mișcare, poți muta unul sau mai multe modele pe rând, în linii drepte și/sau rotindu-le. Rotirea în jurul centrului bazei nu consumă distanță. Baza nu poate trece prin modele inamice sau în afara tablei.", "La final verifici coherency, poziția pe terrain și condițiile specifice tipului de mișcare."], ["Movement", "Set Up", "03.02 · p.14", "Când o unitate este set up, trebuie să fie în coherency, unengaged și să respecte toate condițiile regulii care o plasează. Dacă nu poți plasa toate modelele, unitatea revine în poziția/rezerva inițială.", "Un Deep Strike care nu încape legal nu poate fi plasat parțial."], ["Movement", "Coherency", "03.03 · p.14–15", "Fiecare model trebuie să fie la maximum 2” orizontal și 5” vertical de cel puțin un alt model din unitate și la maximum 9” orizontal și 5” vertical de fiecare model din unitate.", "La End of Turn, modelele unei unități rămase în afara coherency sunt eliminate până când unitatea redevine coherentă."], ["Movement", "Engagement Range", "03.04 · p.14–15", "Engagement Range este zona aflată la 2” orizontal și 5” vertical de un model. Unitățile cu modele în această rază față de inamic sunt engaged.", "Dacă niciun model din unitate nu este engaged, unitatea este unengaged."], ["Attacks", "Selectarea armelor și țintelor", "04.01–04.02 · p.16", "La Shooting poți selecta una sau mai multe arme ranged ale fiecărui model. La Fight trebuie să selectezi o armă melee. Țintele ranged trebuie, în mod normal, să fie vizibile, în range și unengaged.", "La melee poți selecta una sau mai multe unități engaged cu modelul, în limita Attacks a armei."], ["Attacks", "Ordinea rezolvării atacurilor", "04.03 · p.17", "Pentru fiecare unitate țintă: selectezi unitatea inamică, aduni zarurile pentru o armă, rezolvi Attack Sequence, apoi continui cu armele/ținte rămase.", "Atacurile identice pot fi grupate. Atacurile melee împărțite între mai multe ținte trebuie declarate înainte de zaruri."], ["Attacks", "Attack Sequence", "05.00 · p.18–19", "Ordinea este Hit Rolls → Wound Rolls → Save Rolls → Inflict Damage. Rezolvi toate atacurile; pentru fiecare atac, secvența se termină când atacul eșuează sau provoacă damage.", "Critical Hits și Critical Wounds sunt în continuare hits și wounds și pot declanșa abilități."], ["Attacks", "Hit și Wound rolls", "05.01–05.02 · p.18", "Hit roll verifică BS/WS. Wound roll compară Strength cu Toughness: S cel puțin dublu T, mai mare, egal, mai mic sau cel mult jumătate determină praguri progresiv mai dificile.", "Folosește tabelul S vs T de la pagina 18 a PDF-ului; nu presupune automat 4+."], ["Attacks", "Save și Damage", "05.03–05.04 · p.19", "Apărătorul stabilește allocation groups și ordinea alocării. Apoi face save rolls. Un atac provoacă damage dacă nu este oprit de Invulnerable Save sau de Save modificat de AP.", "Damage-ul reduce Wounds; la 0 sau mai puține, modelul este distrus. Atacurile excedentare se pierd când unitatea este distrusă."], ["Other", "Modificarea zarurilor și reroll", "06.00 · p.24–25", "Aplică regulile de modificare și reroll conform ordinii din secțiunea 06. Un reroll înlocuiește zarul ales; același zar nu poate fi reroll-uit de mai multe ori.", "Verifică formularea exactă a abilității: «reroll a hit roll» nu este identic cu «reroll hit rolls of 1»."], ["Battle Round", "Structura turei", "07.00 · p.28–29", "Jocul se desfășoară în battle rounds. Fiecare tură are Start of Turn, Command, Movement, Shooting, Charge, Fight și End of Turn steps/phases, în ordinea indicată.", "Fiecare jucător își joacă tura; ordinea fazelor este aceeași."], ["Command", "Command Phase", "08.00 · p.30–31", "Ordinea: Start of Command Phase; ambii jucători primesc 1 Core CP; Battle-shock pentru unitățile eligibile ale jucătorului activ; Command Abilities; End of Command Phase.", "Battle-shock se verifică pentru unități deja Battle-shocked sau la/sub half-strength."], ["Movement", "Movement Phase și Normal Move", "09.00–09.05 · p.32–33", "În Movement Phase selectezi unități eligibile și le faci Normal Move sau le lași Stationary. Normal Move nu poate depăși Move characteristic și nu poate termina în Engagement Range.", "Verifică eligibilitatea unității înainte de a o selecta."], ["Movement", "Advance Move", "09.06 · p.33", "Unitatea face un Advance roll și adaugă rezultatul la distanța maximă de mișcare. Unitatea care a făcut Advance nu este, în mod normal, eligibilă să tragă sau să declare Charge în acel tur, cu excepțiile explicite din reguli/abilități.", "Nu confunda Advance cu Normal Move; verifică restricțiile de după mișcare."], ["Movement", "Fall Back Move", "09.07 · p.33", "O unitate engaged poate încerca Fall Back. Alege modul permis de regulă: Ordered Retreat sau Desperate Escape; acesta din urmă implică Hazard rolls pentru modele.", "După Fall Back, aplică restricțiile de Shooting/Charge/Actions indicate în regulile fazei."], ["Shooting", "Shooting Phase", "10.00 · p.34–35", "Selectezi unități eligibile să tragă și rezolvi atacurile lor. O unitate engaged nu trage în mod normal, cu excepțiile Close-Quarters Shooting pentru anumite arme și MONSTER/VEHICLE.", "Assault Shooting, Close-Quarters Shooting și Indirect Shooting au condiții și restricții proprii."], ["Charge & Fight", "Charge Phase", "11.00 · p.36–37", "Selectezi unități eligibile, declari ținte, faci Charge roll și muți modelele astfel încât să respecte condițiile de charge și să termine engaged cu țintele.", "O țintă trebuie să fie eligibilă și în raza legală; distanța disponibilă nu garantează că poți ocoli terrain și termina engaged."], ["Charge & Fight", "Fight Phase", "12.00 · p.38–43", "Fight Phase rezolvă mai întâi Fights First combats, apoi Remaining combats. Unitățile selectate pot face Pile-in, atacuri melee și Consolidation conform pașilor lor.", "Fights First influențează ordinea selecției, nu oferă automat un atac suplimentar."], ["Terrain", "Terrain și categorii", "13.00–13.06 · p.46–49", "Terrain features și terrain areas au reguli diferite. Secțiunile Exposed, Light și Dense au efecte specifice asupra mișcării și vizibilității. Moving Vertically tratează urcarea/coborârea.", "Verifică tipul secțiunii terrain și regula specifică pentru INFANTRY, MONSTER și VEHICLE."], ["Terrain", "Visibility", "13.07 · p.50", "Terrain poate afecta vizibilitatea prin Benefit of Cover, Hidden, Obscuring și Solid. Fiecare regulă are propriile condiții; nu sunt sinonime.", "O unitate poate fi vizibilă, dar totuși să beneficieze de cover."], ["Terrain", "Benefit of Cover", "13.08 · p.50", "O unitate primește Benefit of Cover împotriva unui atac ranged dacă fiecare model îndeplinește cel puțin una dintre condiții: are INFANTRY/BEASTS/SWARM și se află într-o terrain area; sau nu este complet vizibil din cauza terrain-ului intermediar. Cover înrăutățește BS-ul atacului cu 1.", "O unitate aflată în spatele altor modele nu primește cover doar pentru că acele modele sunt în față."], ["Terrain", "Hidden", "13.09 · p.50", "Un model poate fi Hidden dacă are INFANTRY/BEASTS/SWARM, se află într-o terrain area cu Dense terrain features și unitatea sa nu a făcut ranged attacks în turul curent sau precedent. Hidden limitează vizibilitatea la Detection Range (implicit 15”).", "Este o regulă distinctă de Benefit of Cover."], ["Terrain", "Obscuring și Solid", "13.10–13.11 · p.50–51", "Terrain areas cu Light sau Dense features sunt Obscuring. Dacă toate liniile de vedere dintre două modele traversează una sau mai multe astfel de zone (cu excepția zonei în care se află unul dintre modele), modelele nu se văd. Dense features au și Solid: nu se trasează line of sight prin goluri închise aflate la 3” sau mai puțin de nivelul solului.", "Solid protejează împotriva liniilor de vedere prin ferestre/uși/găuri mici la nivelul specificat."], ["Objectives", "Objective Control", "14.00 · p.52–53", "Controlul unui objective se determină folosind Objective Control (OC) al modelelor din raza objective marker-ului, conform regulii de misiune.", "OC «-» nu contribuie la control. Battle-shock modifică OC la «-»."], ["Stratagems", "Stratagems", "15.00 · p.54–57", "Stratagems costă CP și pot fi folosite numai în momentul WHEN indicat, asupra TARGET eligibil, respectând EFFECT și RESTRICTIONS.", "Core Stratagems sunt listate în regulament; faction stratagems pot avea reguli suplimentare."], ["Actions", "Actions", "16.00 · p.58–59", "Actions sunt obiective tactice cu condiții de eligibilitate, moment de start, efect și condiții de finalizare. Unele acțiuni pot fi întrerupte sau nu pot fi începute de unități Battle-shocked.", "Citește condițiile specifice ale acțiunii și restricțiile după Shooting/Charge."], ["Advanced", "MONSTERS și VEHICLES", "17.00 · p.62–63", "Această secțiune conține reguli speciale pentru MONSTER și VEHICLE, inclusiv interacțiunea cu Engagement Range și shooting while engaged.", "Nu presupune că un VEHICLE urmează regulile INFANTRY pentru terrain sau etaje."], ["Advanced", "Transports", "18.00 · p.64–65", "Regulile de transport stabilesc ce unități pot embark, cum se face embark/disembark și ce se întâmplă când transportul este distrus.", "Respectă capacitatea și restricțiile de keyword ale transportului; disembark trebuie să fie legal și în coherency."], ["Advanced", "Attached Units", "19.00 · p.66–67", "Un Leader poate fi atașat unei unități Bodyguard în condițiile datasheet-ului. Regulile stabilesc cum funcționează unitatea combinată și cum sunt alocate atacurile.", "Verifică exact ce Leaders pot conduce ce Bodyguard units."], ["Advanced", "Strategic Reserves", "20.00 · p.68–69", "Unitățile din Strategic Reserves nu sunt pe battlefield și intră prin Ingress în condițiile de rundă, margine și distanță descrise de reguli.", "Strategic Reserves nu este același lucru cu Deep Strike; Deep Strike este o Core Ability separată."], ["Advanced", "Flying și Surging", "21.00 · p.70–71", "Secțiunea tratează unitățile care zboară și regulile Surge. Aplică profilul de mișcare și condițiile specifice ale abilității.", "Nu presupune că FLY ignoră orice restricție de terrain sau de set-up."], ["Advanced", "Other Rules and Abilities", "22.00 · p.72–73", "Reguli suplimentare pentru interacțiuni și abilități speciale. Când două reguli par să intre în conflict, aplică regulile de sequencing și priority din regulament.", "Verifică textul exact al abilității și momentul în care se declanșează."], ["Advanced", "Aircraft", "23.00 · p.74–75", "Aircraft au reguli distincte de mișcare, set-up și poziționare. Aplică aceste reguli în loc să presupui că se comportă ca alte VEHICLES.", "Consultă regulile Aircraft înainte de a muta sau plasa o astfel de unitate."], ["Core Abilities", "Deep Strike", "24.09 · p.79", "Unitatea cu Deep Strike poate face Ingress conform regulii acestei abilități, respectând distanțele și restricțiile de plasare aplicabile.", "Deep Strike nu anulează cerințele de coherency, unengaged sau alte restricții de set-up."], ["Core Abilities", "Devastating Wounds", "24.10 · p.79", "Când un atac cu Devastating Wounds produce Critical Wound, secvența acelui atac se încheie și unitatea țintă suferă mortal wounds egale cu Damage-ul armei, aplicate după celelalte atacuri ale unității.", "Folosește formularea exactă din ediția PDF atașată."], ["Core Abilities", "Feel No Pain", "24.12 · p.80", "Feel No Pain X+: de fiecare dată când modelul ar pierde un wound, aruncă un D6; la X+ acel wound nu este pierdut.", "Se face pentru fiecare wound care ar fi pierdut."], ["Core Abilities", "Fights First", "24.13 · p.80", "Dacă fiecare model din unitate are această abilitate, unitatea este Fights First. În Fight Phase, este selectată în pasul Fights First Combats.", "Nu înseamnă că unitatea atacă de două ori."], ["Core Abilities", "Hazardous", "24.15 · p.81", "După ce unitatea a rezolvat toate atacurile cu arme Hazardous selectate, faci Hazard rolls pentru unitate, câte unul pentru fiecare armă Hazardous selectată.", "Nu face Hazard roll după fiecare atac individual; urmează momentul indicat de regulă."], ["Core Abilities", "Heavy", "24.16 · p.81", "În Shooting Phase, un atac cu Heavy primește +1 la hit roll dacă unitatea este unengaged, nu a fost set up în battlefield în acest tur și niciun model nu s-a mișcat mai mult de 3” în acest tur.", "Toate condițiile trebuie îndeplinite."], ["Core Abilities", "Indirect Fire", "24.19 · p.82", "Unitatea poate alege Indirect Shooting dacă îndeplinește condițiile. Armele Indirect Fire pot ținti unități nevizibile, dar ținta primește cover, nu poți rerolla hit rolls și există penalizări speciale la hit rolls.", "Vezi 10.07, p.35, pentru condițiile complete ale Indirect Shooting."], ["Core Abilities", "Infiltrators", "24.20 · p.82", "La deployment, dacă fiecare model din unitate are Infiltrators, unitatea poate fi set up oriunde pe battlefield la mai mult de 8” orizontal de deployment zone-ul adversarului și de toate unitățile inamice.", "Este o regulă de deployment, nu un move în Movement Phase."], ["Core Abilities", "Lethal Hits", "24.23 · p.83", "Un Critical Hit cu o armă Lethal Hits poate alege să wound automat ținta; nu se mai face wound roll pentru acel atac.", "Alegerea auto-wound poate preveni declanșarea unei abilități care cere Critical Wound."], ["Core Abilities", "Precision", "24.28 · p.84", "Când rezolvi atacuri cu Precision, la Allocation Order poți aloca atacul unui CHARACTER model din unitatea țintă, în condițiile regulii.", "Precision nu permite ignorarea tuturor celorlalte reguli de alocare."], ["Core Abilities", "Scouts", "24.31 · p.84", "Scouts X” permite un Scout Move înainte de începerea primei ture, în condițiile regulii. Distanța și eligibilitatea sunt date de valoarea X și de modelele din unitate.", "Verifică regulile pentru unități cu valori Scouts diferite."], ["Core Abilities", "Stealth", "24.33 · p.85", "Dacă fiecare model din unitate are Stealth, unitatea primește Benefit of Cover împotriva atacurilor ranged care o țintesc.", "Stealth acordă cover; nu face unitatea automat Hidden sau Obscured."], ["Core Abilities", "Sustained Hits", "24.36 · p.85", "Un Critical Hit cu Sustained Hits X produce X hit-uri suplimentare asupra țintei.", "Exemplul din regulament: Sustained Hits 2 înseamnă un hit inițial plus două hit-uri suplimentare."], ["Core Abilities", "Torrent și Twin-linked", "24.37–24.38 · p.85", "Torrent: atacul lovește automat. Twin-linked: poți rerolla wound roll pentru fiecare atac cu arma respectivă.", "Torrent elimină Hit Roll; Twin-linked modifică Wound Roll."]];

// Expanded reference entries transcribed and paraphrased from the attached Core Rules PDF.
RULES.push(
["Core Abilities","Anti-X","24.03 · p.79","Forma: [ANTI-X Y+]. Dacă ținta are keyword-ul X, un Wound Roll nemodificat de Y+ este Critical Wound.","Exemplu: ANTI-VEHICLE 4+ produce Critical Wound pe 4+ împotriva unei unități VEHICLE.","Verifică keyword-ul unității-țintă, nu modelul individual. Pragul este pe Wound Roll nemodificat. Nu transformă automat atacul într-un wound: este un Critical Wound, deci poate declanșa efecte care cer Critical Wound.","Nu se aplică dacă ținta nu are keyword-ul cerut. Dacă apar mai multe instanțe ale aceleiași abilități, se aplică regula de duplicated abilities (24.02)."],
["Core Abilities","Assault","24.04 · p.79","O unitate care conține cel puțin un model cu armă [ASSAULT] poate folosi Assault Shooting (10.05).","Poți trage cu arma Assault chiar dacă unitatea a făcut Advance, dacă îndeplinește condițiile Assault Shooting.","Assault este o permisiune de a folosi modul Assault Shooting; nu înseamnă că toate armele unității devin Assault. Verifică arma selectată și eligibilitatea unității pentru tipul de shooting.","După shooting, unitatea nu este eligibilă să înceapă o Action în acea fază, conform regulii Shooting."],
["Core Abilities","Blast","24.05 · p.79","La adunarea attack dice, adaugi un atac pentru fiecare cinci modele din unitatea-țintă la Select Targets (rotunjit în jos). Dacă arma are [BLAST X], adaugi X atacuri pentru fiecare cinci modele.","A=3, Blast 2, țintă cu 12 modele: +4 atacuri, deci 7 în total.","Numărul de modele se fixează în Select Targets step. Bonusul se calculează pe fiecare armă Blast în parte.","O armă Blast nu poate ținti o unitate cu care atacatorul este engaged în condițiile regulii de shooting engaged. Nu aplica bonusul pentru fracțiuni de cinci modele."],
["Core Abilities","Cleave","24.06 · p.79","Forma: [CLEAVE X]. Dacă toate atacurile acelei arme au o singură țintă selectată, adaugi X attack dice pentru fiecare cinci modele din unitatea-țintă (rotunjit în jos).","Cleave 1, A=3, țintă cu 16 modele: +3 atacuri, total 6.","Condiția este să fi selectat o singură țintă pentru toate atacurile armei. Numără modelele din țintă la Select Targets step.","Dacă împarți atacurile armei între mai multe ținte, nu primești atacurile bonus Cleave."],
["Core Abilities","Close-quarters / Pistol","24.07 · p.80; 24.27 · p.83","Unitățile cu una sau mai multe arme [CLOSE-QUARTERS] pot folosi Close-Quarters Shooting (10.06). Pentru modelele non-MONSTER/non-VEHICLE, la un alt tip de shooting alegi fie armele Close-Quarters, fie celelalte arme ranged; nu ambele. [PISTOL] și [CLOSE-QUARTERS] sunt identice pentru toate regulile.","Un model INFANTRY cu pistol și rifle nu trage cu ambele în aceeași selecție de shooting: alege categoria permisă.","Close-Quarters permite shooting în condițiile secțiunii 10.06 și are limitări pentru armele selectate. MONSTER/VEHICLE au tratament separat când sunt engaged.","Nu trata Pistol ca o abilitate diferită de Close-Quarters în această ediție a PDF-ului."],
["Core Abilities","Deadly Demise","24.08 · p.80","Forma: Deadly Demise X. Când modelul este distrus, după ce unitățile îmbarcate (dacă există) au făcut Emergency Disembark, arunci un D6. La 6, fiecare unitate aflată la 6\" de model suferă X mortal wounds; dacă X este aleatoriu, arunci separat pentru fiecare unitate.","Un transport distrus își rezolvă mai întâi atacurile nerezolvate, apoi Emergency Disembark, apoi Deadly Demise, apoi este scos de pe battlefield.","Ordinea momentelor este importantă: nu arunca Deadly Demise înainte de Emergency Disembark. Efectul poate afecta și unități friendly aflate în raza de 6\".","La rezultat diferit de 6 nu se declanșează. Pentru X aleatoriu, valoarea nu este comună tuturor unităților."],
["Core Abilities","Deep Strike","24.09 · p.80","La Ingress, dacă fiecare model din unitate are Deep Strike, unitatea poate fi set up oriunde pe battlefield la mai mult de 8\" orizontal de toate unitățile inamice, inclusiv în deployment zone-ul adversarului.","Deep Strike poate permite intrarea în zona adversă, dar trebuie să păstrezi peste 8\" față de toate unitățile inamice.","Deep Strike modifică locul legal de set-up la Ingress. Respectă în continuare cerințele generale de set-up: unitatea completă, coherency și toate modelele plasate legal.","Nu confunda Deep Strike cu Strategic Reserves: condițiile de intrare și marginile tablei sunt diferite. Nu poți plasa doar o parte din unitate."],
["Core Abilities","Devastating Wounds","24.10 · p.80","Când un atac cu [DEVASTATING WOUNDS] produce Critical Wound, Attack Sequence pentru acel atac se încheie și ținta suferă mortal wounds egale cu Damage-ul armei. Se aplică după damage-ul normal al atacurilor respective. Mortal wounds din această abilitate pot distruge maximum un model per Critical Wound; restul se pierd.","D=3 împotriva unui model cu 2 Wounds rămase: 2 mortal wounds distrug modelul, a treia se pierde.","Nu mai faci Save Roll pentru acel atac după Critical Wound; urmează efectul Devastating Wounds. Mortal wounds sunt rezolvate după damage-ul normal produs de acele atacuri.","Nu presupune că surplusul mortal wounds trece la următorul model: limita de un model per Critical Wound este explicită."],
["Core Abilities","Extra Attacks","24.11 · p.81","Când unitatea luptă, modelele cu arme [EXTRA ATTACKS] atacă cu acele arme în plus față de celelalte arme. La Select Weapons, pentru fiecare model selectezi toate armele Extra Attacks și, dacă este posibil, una dintre celelalte arme melee.","Un model cu o armă melee normală și una Extra Attacks le poate folosi pe ambele în aceeași Fight.","Extra Attacks nu înlocuiește alegerea armei melee normale. Respectă instrucțiunea specială din Select Weapons pentru fiecare model.","Nu permite selectarea mai multor arme non-Extra-Attacks decât permite regula generală."],
["Core Abilities","Firing Deck","24.14 · p.81","Firing Deck X: când TRANSPORT-ul este selectat să tragă, poți selecta până la X modele îmbarcate; pentru fiecare alegi o armă ranged (nu One Shot). Transportul are acele arme în plus până își termină toate atacurile. Unitățile îmbarcate nu sunt eligibile să tragă până la sfârșitul turei.","Firing Deck 2 permite selectarea a maximum două modele îmbarcate pentru a contribui cu câte o armă ranged.","Modelele alese nu pot proveni din unități care au fost deja selectate să tragă în această fază. Armele sunt folosite ca și cum ar aparține transportului pentru rezolvarea atacurilor.","Nu selecta arme [ONE SHOT]. După folosirea Firing Deck, unitățile îmbarcate nu trag separat în aceeași tură."],
["Core Abilities","Feel No Pain","24.12 · p.81","Forma: Feel No Pain X+. De fiecare dată când modelul ar pierde un Wound, arunci un D6; la X+ acel Wound nu este pierdut.","Feel No Pain 5+: pentru fiecare Wound care ar fi pierdut, un rezultat 5 sau 6 îl anulează.","Se aruncă pentru fiecare Wound, nu o singură dată pentru întregul atac. Aplică după ce ai determinat că modelul ar pierde Wound.","Nu este un Save Roll și nu modifică Save characteristic. Nu anula damage înainte să fie determinată pierderea de Wounds."],
["Core Abilities","Fights First","24.13 · p.81","O unitate este Fights First numai dacă fiecare model din ea are această abilitate. Este selectată în pasul Resolve Fights First Combats al Fight Phase.","O unitate care a făcut un Charge Move primește Fights First până la sfârșitul turei, conform Charge Move 11.04.","Fights First stabilește ordinea selecției în Fight Phase. Ambii jucători au oportunități de selecție în pașii corespunzători.","Nu acordă automat două activări sau atacuri suplimentare."],
["Core Abilities","Hazardous","24.15 · p.81","După ce unitatea selectată să tragă sau să lupte și-a rezolvat toate atacurile, faci Hazard Rolls egale cu numărul armelor Hazardous selectate în Select Weapons.","Dacă unitatea a selectat două arme Hazardous, face două Hazard Rolls după ce termină toate atacurile.","Hazard Roll: D6; la 1–2 eșuează și unitatea suferă 1 mortal wound, sau 3 mortal wounds dacă fiecare model din unitate este MONSTER/VEHICLE. Mai multe hazard rolls se aruncă simultan.","Nu face un Hazard Roll per atac. Numără armele Hazardous selectate, apoi aplică secțiunea 06.03."],
["Core Abilities","Heavy","24.16 · p.82","În Shooting Phase, fiecare atac cu [HEAVY] primește +1 la Hit Roll dacă toate sunt adevărate: unitatea este unengaged; nu a fost set up pe battlefield în această tură; niciun model nu s-a mișcat mai mult de 3\" în această tură.","Dacă un singur model al unității s-a deplasat 4\", condiția de Heavy nu este îndeplinită pentru unitate.","Verifică toate cele trei condiții pentru unitatea care atacă. Bonusul este la Hit Roll, nu la BS.","Nu acorda +1 dacă unitatea a fost set up în turul curent sau este engaged."],
["Core Abilities","Hover","24.17 · p.82","Când unitatea folosește Take to the Skies (21.03), nu scade 2\" din distanța maximă de mișcare.","O unitate cu Hover care ia to the skies își păstrează distanța maximă normală.","Hover schimbă doar penalizarea de distanță din regula Take to the Skies.","Nu acordă automat o mișcare suplimentară și nu înlătură alte condiții ale regulii Flying."],
["Core Abilities","Ignores Cover","24.18 · p.82","Atacurile cu [IGNORES COVER] nu permit țintei să beneficieze de Benefit of Cover împotriva acelui atac, inclusiv cover obținut prin abilități precum Stealth.","Stealth nu oferă protecție de cover împotriva atacurilor cu Ignores Cover.","Efectul este specific atacului cu arma respectivă; nu elimină cover pentru alte atacuri din aceeași unitate.","Nu confundă Benefit of Cover cu Hidden sau Obscuring; ability-ul spune că ignoră cover, nu toate regulile de vizibilitate."],
["Core Abilities","Indirect Fire","24.19 · p.82","Unitățile cu arme [INDIRECT FIRE] pot folosi Indirect Shooting (10.07). Armele pot ținti unități nevizibile. Ținta primește Benefit of Cover; nu poți rerolla Hit Rolls; Hit Roll nemodificat 1–5 eșuează, cu excepția situației în care unitatea a rămas Stationary și ținta este vizibilă unei unități friendly: atunci 1–3 eșuează.","Dacă tragi indirect fără ca ținta să fie vizibilă, doar 6 reușește la Hit Roll nemodificat; cu condițiile speciale de Stationary și friendly visibility, 4–6 pot reuși.","Condițiile de eligibilitate: unitatea este unengaged, nu a făcut Advance în această tură și are cel puțin o armă Indirect Fire.","Nu poți rerolla Hit Rolls pentru atacurile Indirect Fire. Nu presupune că celelalte arme ale unității trag indirect."],
["Core Abilities","Infiltrators","24.20 · p.82","La deployment, dacă fiecare model din unitate are Infiltrators, unitatea poate fi set up oriunde pe battlefield la peste 8\" orizontal de deployment zone-ul adversarului și de toate unitățile inamice.","Infiltrators permite poziționare avansată înainte de prima tură, dar trebuie respectate ambele distanțe de peste 8\".","Este o regulă de deployment. Nu este Scout Move și nu este Deep Strike/In­gress.","Dacă un singur model din unitate nu are Infiltrators, condiția «every model» nu este îndeplinită."],
["Core Abilities","Lance","24.21 · p.82","Fiecare atac cu [LANCE] primește +1 la Wound Roll dacă unitatea atacatoare a făcut un Charge Move în această tură.","După un charge reușit, atacurile Lance beneficiază de +1 la wound.","Verifică dacă unitatea a făcut efectiv Charge Move în această tură. Bonusul se aplică la Wound Roll.","Nu se aplică doar pentru că unitatea a declarat charge; trebuie să fi făcut Charge Move."],
["Core Abilities","Leader / Support","24.22; 24.34 · p.82, 85","Leader și Support trimit la regulile Attached Units (19). Ele descriu rolul modelului în formarea unei unități atașate și suportul specializat în unitatea Bodyguard.","Verifică datasheet-ul Leader-ului și lista de Bodyguard pe care o poate conduce.","Folosește regulile Attached Units pentru momentul atașării, unitatea combinată, keywords și alocarea atacurilor.","Nu presupune că orice Leader poate conduce orice unitate. Compatibilitatea este determinată de datasheet."],
["Core Abilities","Lethal Hits","24.23 · p.82–83","La un Critical Hit cu [LETHAL HITS], poți alege ca atacul să wound automat ținta; nu mai faci Wound Roll pentru acel atac.","Critical Hit cu Lethal Hits poate ocoli Wound Roll, dar atunci nu poate genera Critical Wound prin acel roll.","Decizia de auto-wound este opțională. Efectul poate fi util pentru a trece de Toughness, dar poate pierde declanșatoare care cer Critical Wound.","Nu combina auto-wound-ul cu un Wound Roll ulterior pentru același atac."],
["Core Abilities","Lone Operative","24.24 · p.83","Dacă unitatea nu face parte dintr-o Attached Unit, nu este vizibilă pentru modele inamice decât dacă acestea sunt la 12\" sau mai aproape. Nu poate fi țintită de arme Indirect Fire decât dacă modelul atacator este la 12\" sau mai aproape. Varianta Lone Operative X\" înlocuiește 12\" cu X\".","Un Lone Operative la 13\" nu poate fi ales ca țintă de un model inamic aflat mai departe de 12\".","Verifică dacă unitatea face parte dintr-o Attached Unit; excepția elimină protecția descrisă aici.","Nu este invulnerabilitate și nu oprește atacurile de la distanța permisă."],
["Core Abilities","Melta","24.25 · p.83","Forma: [MELTA X]. Dacă ținta era în jumătate din Range-ul armei la Select Targets, adaugi X la Damage characteristic pentru atacurile acelei arme.","Melta 2 cu Damage D6 devine D6+2 dacă ținta este la jumătate de range sau mai aproape.","Măsoară distanța la Select Targets step. Bonusul se aplică Damage-ului, nu numărului de atacuri.","Dacă ținta nu era în half range la Select Targets, nu primește bonusul chiar dacă se apropie ulterior."],
["Core Abilities","One Shot","24.26 · p.83","Fiecare armă [ONE SHOT] poate fi selectată pentru atac o singură dată per battle. Dacă un model distrus revine într-o unitate, arma deja folosită nu poate fi selectată din nou. O unitate nou adăugată armatei poate folosi arma o dată.","După ce ai tras cu o armă One Shot, nu o mai poți selecta din nou în aceeași bătălie.","Limitarea este per armă/model conform regulii. Reîntoarcerea unui model distrus nu resetează utilizarea.","Nu confunda One Shot cu o limită o dată pe tură."],
["Core Abilities","Precision","24.28 · p.83","La începutul Allocation Order, dacă unitatea țintă conține CHARACTER vizibil pentru cel puțin unul dintre modelele atacatoare, jucătorul activ poate selecta un allocation group care conține acel CHARACTER. Grupul devine current allocation group pentru atacurile respective sau până este distrus.","Precision poate direcționa atacuri către un CHARACTER vizibil din unitatea atașată.","Condiția de vizibilitate se verifică față de unul sau mai multe modele atacatoare. Selectarea grupului are loc la începutul Allocation Order.","Precision nu permite să alegi orice CHARACTER ascuns sau nevizibil. Respectă condițiile de grup și vizibilitate."],
["Core Abilities","Psychic","24.29 · p.84","Atacurile cu [PSYCHIC] pot ignora orice modificatori sau toți modificatorii la BS/WS și la Hit Roll. Aceste atacuri sunt psychic attacks, aspect relevant pentru alte reguli.","Un atac Psychic poate ignora un modificator negativ la Hit Roll, în limitele textului abilității.","Alegerea este de a ignora oricare sau toți modificatorii menționați. Identificarea ca psychic attack poate activa alte reguli care fac referire la psychic.","Nu extinde efectul la Wound Rolls, Save Rolls sau alte caracteristici care nu sunt enumerate."],
["Core Abilities","Rapid Fire","24.30 · p.84","Forma: [RAPID FIRE X]. La adunarea attack dice, adaugi X atacuri dacă ținta era în half range la Select Targets step.","Rapid Fire 1, A=1, ținta în half range: total 2 atacuri.","Verifică half range în momentul Select Targets. Bonusul se adaugă la Attack characteristic.","Nu adăuga atacuri dacă ținta era în afara half range la Select Targets."],
["Core Abilities","Scouts și Scout Move","24.31–24.32 · p.84","Scouts X\" se folosește în Resolve Pre-battle Abilities dacă fiecare model din unitate are abilitatea: unitatea din Strategic Reserves poate fi set up wholly within deployment zone; dacă este deja wholly within deployment zone poate face Scout Move; sau un Dedicated Transport wholly within deployment zone poate face Scout Move dacă toate modelele îmbarcate au Scouts. Scout Move are distanța maximă X\" și se termină la peste 8\" orizontal de toate unitățile inamice.","Scouts 6\" permite un Scout Move de maximum 6\", cu condiția de distanță finală >8\" față de inamici.","Scout Move se rezolvă în Resolve Pre-battle Abilities, nu în Movement Phase. Aplică regulile Moving și verifică distanța finală.","Dacă nu fiecare model din unitate are abilitatea, unitatea nu îndeplinește condiția generală. Pentru valori diferite de Scouts se aplică regula de duplicated abilities 24.02."],
["Core Abilities","Stealth","24.33 · p.85","Dacă fiecare model din unitate are Stealth, de fiecare dată când un ranged attack țintește unitatea, aceasta are Benefit of Cover împotriva atacului.","Stealth oferă cover împotriva atacurilor ranged care țintesc unitatea.","Este o sursă de Benefit of Cover; aplică regulile de cover pentru acel atac.","Stealth nu conferă Hidden, nu ascunde unitatea și nu anulează line of sight."],
["Core Abilities","Super-heavy Walker","24.35 · p.85","La Normal, Advance sau Fall Back Move, modelele pot trece prin modele (inclusiv MONSTER/VEHICLE, dar nu TITANIC) și pot traversa orizontal secțiuni de terrain features de maximum 4\" înălțime. Înainte de mișcare poți acorda keyword-ul MOBILE tuturor modelelor până la finalul mișcării; dacă faci asta, la final arunci D6 și la 1 unitatea devine Battle-shocked.","Un model cu Super-heavy Walker poate trece printr-un model VEHICLE non-TITANIC în timpul unuia dintre tipurile de mișcare enumerate.","MOBILE permite interacțiunea indicată cu Dense terrain features. Alegerea de a deveni MOBILE trebuie făcută înainte de mutare.","Nu se aplică la Charge Move sau orice alt tip de move care nu este enumerat. TITANIC este exclus din traversarea modelelor."],
["Core Abilities","Sustained Hits","24.36 · p.85","Forma: [SUSTAINED HITS X]. Un Critical Hit produce X hit-uri suplimentare asupra țintei.","Sustained Hits 2: Critical Hit-ul inițial plus două hit-uri suplimentare = trei hit-uri în total.","Hit-urile suplimentare nu sunt Critical Hits în sine decât dacă o altă regulă spune asta. Ele continuă secvența de atac conform regulilor.","Nu confunda X hit-uri suplimentare cu X atacuri suplimentare la Select Targets."],
["Core Abilities","Torrent","24.37 · p.85","Fiecare atac cu [TORRENT] lovește automat ținta; nu faci Hit Roll pentru acel atac.","Torrent elimină Hit Roll, dar atacul continuă la Wound Roll.","După auto-hit, continuă secvența normală cu Wound Roll, Save Roll și damage, după caz.","Nu înseamnă auto-wound și nu ocolește Save Roll."],
["Core Abilities","Twin-linked","24.38 · p.85","La fiecare atac cu [TWIN-LINKED], poți rerolla Wound Roll.","Poți rerolla un Wound Roll nereușit sau reușit pentru fiecare atac Twin-linked, dacă dorești.","Reroll-ul înlocuiește rezultatul inițial și nu poate fi reroll-uit din nou. Este un reroll al Wound Roll, nu al întregului atac.","Nu rerolla Hit Roll sau Save Roll prin Twin-linked."]
);

// Practical step-by-step notes for the main game sequence and advanced rules.
var RULE_DETAILS={
"Unități și modele":["Când o regulă spune unit, verifică toate modelele care fac parte din unitate în acel moment. Dacă o unitate are un Leader atașat, aplică și regulile specifice Attached Units.","Nu confunda modelul cu unitatea: unele efecte aleg un model, altele o unitate întreagă. Citește exact substantivul folosit de regulă."],
"Măsurarea distanțelor":["Măsoară cea mai scurtă distanță între bazele modelelor, dacă regula nu precizează alt punct de măsurare. Distanțele sunt în inch. Distanțele verticale și orizontale pot fi tratate separat când regula spune asta.","Nu măsura din centrul bazei decât dacă o regulă specifică cere acest lucru."],
"Leadership și Battle-shock":["Battle-shock se verifică în Command Phase pentru unitățile eligibile. Arunci 2D6 și compari rezultatul cu Leadership-ul cerut. La eșec, unitatea devine Battle-shocked până la începutul următoarei Command Phase a jucătorului care o controlează.","Cât timp este Battle-shocked, OC este -, nu poate fi țintită de stratageme de către propriul jucător și nu poate începe sau finaliza Actions. Verifică și orice alte efecte menționate de misiune."],
"Caracteristici și arme":["M este distanța de mișcare; T este Toughness; Sv este Save; InSv este Invulnerable Save; W este Wounds; Ld este Leadership; OC este Objective Control. Profilul armei are Range, A, BS/WS, S, AP și D.","Dacă un profil afișează «-», caracteristica respectivă nu poate fi folosită pentru acea armă/model în mod normal. Keyword-urile pot activa reguli suplimentare."],
"Principii de mișcare":["Mută modelele pe rând, fără să depășești distanța maximă. Modelele nu pot trece prin alte modele sau în afara battlefield-ului, cu excepțiile explicite. Rotirea în jurul centrului bazei nu consumă distanță.","La final verifică poziția fiecărui model, coherency, Engagement Range și condițiile terrain. Nu începe următorul model până nu ai încheiat legal mișcarea celui precedent."],
"Set Up":["Set-up nu este un move. Plasează întreaga unitate în poziție legală și în coherency. Dacă nu poți plasa toate modelele în condițiile cerute, urmează regula sursei care a permis set-up; nu lăsa unitatea plasată parțial.","Set-up poate declanșa reguli care se referă la unități nou plasate. Verifică dacă regula permite set-up în Engagement Range sau impune o distanță minimă."],
"Coherency":["La verificare, fiecare model trebuie să fie la maximum 2 inch orizontal și 5 inch vertical de cel puțin un alt model din unitate. În plus, trebuie să fie la maximum 9 inch orizontal și 5 inch vertical de fiecare model din unitate.","Verifică coherency după mișcare și la End of Turn. Dacă unitatea rămâne necoherentă la End of Turn, elimină modele până când este din nou coherentă, conform regulii."],
"Engagement Range":["Engagement Range este 2 inch orizontal și 5 inch vertical. Unitatea este engaged dacă cel puțin un model al ei se află în Engagement Range a unui inamic.","Engagement Range blochează sau modifică eligibilitatea pentru Normal Move, shooting și charge. Verifică fiecare model și nu confunda engaged cu simpla apropiere vizuală."],
"Selectarea armelor și țintelor":["În shooting, selectează armele ranged ale modelelor și țintele legale. În fight, selectează arme melee. O armă poate ataca doar ținte care respectă range, visibility și restricțiile tipului de atac.","Poți împărți atacurile unui model între ținte dacă declari împărțirea la momentul corect. Pentru melee, țintele trebuie să fie engaged cu modelul atacator."],
"Ordinea rezolvării atacurilor":["Pentru fiecare armă și țintă: stabilește numărul de attack dice, aruncă Hit Rolls, apoi Wound Rolls, apoi apărătorul face Allocation Order și Save Rolls, iar la final se aplică Damage.","Atacurile identice pot fi grupate, dar efectele care cer o anumită ordine sau alegere trebuie rezolvate la momentul lor. Nu trece la următoarea armă până nu ai terminat atacurile curente."],
"Attack Sequence":["Secvența unui atac: Hit Roll → Wound Roll → Allocation Order → Save Roll → Inflict Damage. Un atac care ratează sau nu wound-uiește se oprește la pasul respectiv.","Critical Hit și Critical Wound sunt rezultate nemodificate de 6, dacă abilitatea nu stabilește alt prag. Abilitățile pot modifica secvența, de exemplu Torrent, Lethal Hits sau Devastating Wounds."],
"Hit și Wound rolls":["Hit Roll compară rezultatul zarului cu BS/WS. Wound Roll compară Strength cu Toughness: S cel puțin dublu T = 2+; S mai mare T = 3+; S egal T = 4+; S mai mic T = 5+; S cel mult jumătate T = 6+.","Aplică modificatorii în ordinea din secțiunea 06. Unmodified roll este rezultatul zarului înainte de modificatori."],
"Save și Damage":["Apărătorul alocă atacurile unui model conform Allocation Order, apoi face Save Roll. AP modifică protecția armurii; Invulnerable Save poate fi folosită în locul Save-ului normal dacă este mai bună.","Damage reduce Wounds ale modelului alocat. Când ajunge la 0 Wounds, modelul este distrus. Damage-ul rămas al aceluiași atac nu se transferă la alt model, cu excepțiile/efectele explicite."],
"Modificarea zarurilor și reroll":["Reroll înseamnă să arunci din nou zarul și să folosești noul rezultat. Un zar nu poate fi reroll-uit de mai multe ori. Dacă o regulă spune reroll a roll, poți rerolla rezultatul ales; dacă spune rolls of 1, doar zarurile cu 1.","Modificatorii la rolls sunt limitați de regulile generale din secțiunea 06. Verifică dacă abilitatea afectează rezultatul nemodificat sau rezultatul final."],
"Command Phase":["Începe cu Start of Command Phase, apoi ambii jucători primesc 1 Core CP. Jucătorul activ rezolvă Battle-shock pentru unitățile eligibile, apoi Command Abilities și End of Command Phase.","Nu uita că CP este primit și de jucătorul care nu este activ. Rezolvă efectele care spun «at start» înainte să treci la pasul următor."],
"Movement Phase și Normal Move":["Selectează o unitate eligibilă și declară Normal Move sau Stationary. Mută modelele în limita Move characteristic. Normal Move nu poate termina în Engagement Range.","O unitate engaged nu este în mod normal eligibilă pentru Normal Move. Verifică excepțiile din reguli și abilități înainte de a muta."],
"Advance Move":["Când selectezi Advance, arunci un D6 și adaugi rezultatul la Move characteristic pentru distanța maximă. Unitatea este considerată că a făcut Advance Move.","După Advance, unitatea nu este în mod normal eligibilă să tragă sau să declare Charge în această tură. Assault Shooting și alte excepții explicite pot schimba eligibilitatea."],
"Fall Back Move":["Unitatea engaged poate fi selectată pentru Fall Back dacă este eligibilă. Mută modelele în afara Engagement Range, respectând Move characteristic și regulile de traversare.","Ordered Retreat și Desperate Escape au condiții diferite. Desperate Escape cere Hazard Rolls; verifică regula pentru numărul de zaruri și consecințe."],
"Shooting Phase":["Alege unitățile eligibile una câte una. Pentru fiecare, selectează tipul de shooting disponibil, armele și țintele, apoi rezolvă atacurile. O unitate poate trage o singură dată în fază.","O unitate care a făcut Advance sau Fall Back are restricții. O unitate engaged nu trage normal; Close-Quarters Shooting și regulile MONSTER/VEHICLE pot permite atacuri în condițiile lor."],
"Charge Phase":["Alege o unitate eligibilă care nu este engaged, nu a făcut Advance/Fall Back și are cel puțin o unitate inamică în 12 inch. Declară țintele, aruncă 2D6 și încearcă Charge Move.","Fiecare model trebuie să se apropie de o țintă; dacă poate termina la 1 inch trebuie să o facă, iar dacă poate termina engaged trebuie să o facă. La final trebuie să fii engaged cu toate charge targets și cu nicio altă unitate inamică."],
"Fight Phase":["Rezolvă Start of Fight Phase, apoi Pile In, Fight, Consolidate și End of Fight Phase. Mai întâi se rezolvă Fights First combats, apoi Remaining Combats.","O unitate eligibilă trebuie selectată să lupte. Pile-in și Consolidate sunt mișcări distincte cu propriile condiții; nu sunt obligatorii dacă nu poți sau nu dorești să le faci, potrivit regulii."],
"Terrain și categorii":["Înainte de joc, identifică terrain features și terrain areas, inclusiv dacă sunt Light sau Dense. Aplică regulile de mișcare verticală și restricțiile specifice pentru INFANTRY, MONSTER și VEHICLE.","Terrain area este zona definită de footprint; terrain feature este obiectul/elementul fizic. Nu trata automat ambele concepte ca fiind același lucru."],
"Visibility":["Line of sight există dacă poți trasa o linie imaginară de 1 mm de la orice parte a modelului observator la orice parte a modelului observat, ignorând celelalte modele din unitățile celor două modele.","Un model poate fi visible fără să fie fully visible. O unitate este visible dacă cel puțin un model al ei este visible; este fully visible doar dacă fiecare model este fully visible."],
"Benefit of Cover":["Pentru fiecare atac ranged verifică dacă toate modelele unității țintă îndeplinesc cel puțin una dintre condițiile de cover din 13.08. Cover îmbunătățește protecția conform regulii Save din această ediție.","Cover este verificat pentru atacul curent. Unele arme, precum Ignores Cover, anulează beneficiul împotriva atacului lor."],
"Hidden":["Hidden este o regulă separată de cover. Verifică keyword-urile unității, poziția într-o terrain area cu Dense terrain features și dacă unitatea a făcut ranged attacks în turul curent sau precedent. Detection Range implicit este 15 inch.","Hidden afectează vizibilitatea/țintirea potrivit regulii sale; nu înseamnă că modelul este complet scos din joc sau imun la orice atac."],
"Obscuring și Solid":["Light și Dense terrain features din terrain areas sunt Obscuring. Dacă toate liniile de vedere dintre modele traversează una sau mai multe asemenea zone, modelele nu se văd, cu excepția zonei în care se află unul dintre modele.","Dense terrain features au Solid: nu trasezi line of sight prin goluri închise aflate la 3 inch sau mai puțin de nivelul solului. Aplică separat Obscuring și Solid."],
"Objective Control":["Pentru fiecare objective marker, însumează OC al modelelor eligibile din range. Jucătorul cu total OC mai mare controlează markerul; egalitatea înseamnă că statusul de control nu se schimbă, conform regulii de obiective.","Battle-shocked models au OC «-» și nu contribuie. Respectă și condițiile speciale ale misiunii și regula obiectivelor care nu sunt într-o terrain area."],
"Stratagems":["Citește toate câmpurile: WHEN, TARGET, EFFECT și RESTRICTIONS. Plătește CP la momentul folosirii și verifică dacă stratagemul poate fi folosit în tura/faza respectivă.","Un jucător nu poate folosi același stratagem de mai multe ori în aceeași fază; în mod normal aceeași unitate nu poate fi ținta mai multor stratageme în aceeași fază, conform 15.01."],
"Actions":["Pentru fiecare Action verifică unitatea eligibilă, momentul în care poate începe, ce trebuie să facă unitatea și condițiile de finalizare. Unele Actions se finalizează la un moment ulterior, nu imediat.","Battle-shocked units nu pot începe sau finaliza Actions. Shooting, Charge, Fall Back sau alte acțiuni pot împiedica începerea ori pot întrerupe Action, conform textului ei."],
"MONSTERS și VEHICLES":["MONSTER și VEHICLE pot avea reguli speciale când sunt engaged și trag. Pentru fiecare model, verifică penalizarea la Hit Roll și excepția Close-Quarters. Blast rămâne interzis împotriva unității engaged cu atacatorul.","Modelele non-MONSTER/non-VEHICLE din aceeași unitate urmează restricțiile lor separate. Nu extinde excepția MONSTER/VEHICLE la toate modelele unității."],
"Transports":["Verifică ce unități pot embark, capacitatea și restricțiile de keyword ale transportului. Embark are loc când unitatea îndeplinește condițiile de poziție; disembark plasează modelele în raza și forma permise de regulă.","Când transportul este distrus, unitățile îmbarcate fac Emergency Disembark înainte de rezolvarea Deadly Demise. Dacă nu pot fi plasate legal, aplică pierderile indicate de regula transportului."],
"Attached Units":["Un Leader se atașează unei unități Bodyguard în condițiile datasheet-ului și regulii 19. În timpul jocului, unitatea combinată este tratată ca o singură unitate pentru multe efecte, dar păstrează grupurile de alocare și caracteristicile relevante.","Atacurile se alocă conform grupurilor din Attached Units. Când grupul Bodyguard este distrus, Leader-ul poate deveni o unitate separată; verifică momentul și condițiile din 19."],
"Strategic Reserves":["Alegi unitățile în Declare Battle Formations. Limita este 50% din total points (incluzând transporturile îmbarcate), conform regulii. Ingress este disponibil începând cu Battle Round 2 și are condiții de margine/distanță.","Înainte de Battle Round 3, unitățile nu pot intra în deployment zone-ul adversarului. Unitățile care nu au intrat până la sfârșitul Battle Round 3 sunt distruse, cu excepțiile explicite."],
"Flying și Surging":["FLY permite unității să folosească Take to the Skies pentru anumite tipuri de move, ignorând distanța verticală și trecând prin modele/terrain în condițiile secțiunii 21.03. Există penalizarea de 2 inch la distanța maximă.","Surge Move are declanșator și condiții proprii: unitatea trebuie să fie eligibilă, unengaged și să nu fi făcut deja move în faza respectivă. Urmează cel mai apropiat inamic și limitele de Engagement Range."],
"Other Rules and Abilities":["Auras, faction abilities, psychic abilities, wargear abilities și Plunging Fire sunt tratate în secțiunea 22. Verifică raza, unitățile afectate și momentul în care abilitatea este activă.","Nu presupune că toate auras se cumulează sau că o abilitate de faction se aplică tuturor unităților; urmează textul exact al datasheet-ului/regulii."],
"Aircraft":["AIRCRAFT sunt plasate în Strategic Reserves la deployment și sunt eligibile doar pentru Ingress Move. La sfârșitul turei adversarului, Aircraft-urile tale aflate pe battlefield revin în Strategic Reserves.","Aircraft nu pot declara Charge. Doar unitățile FLYING le pot selecta ca charge targets și doar modelele FLYING pot face melee attacks împotriva lor."]
};
RULES.forEach(function(r){var d=RULE_DETAILS[r[1]];if(d){r[5]=d[0];r[6]=d[1];}});
var cats=["Toate"].concat(Array.from(new Set(RULES.map(function(x){return x[0]}))));
var active="Toate";
function renderRules(){
 var q=($("q").value||"").toLocaleLowerCase("ro");
 var a=RULES.filter(function(x){return (active==="Toate"||x[0]===active)&&x.join(" ").toLocaleLowerCase("ro").indexOf(q)>=0});
 $("count").textContent=a.length+" reguli găsite · "+RULES.length+" fișe · apasă o fișă pentru explicația completă";
 $("results").innerHTML=a.length?a.map(function(x,i){return '<button type="button" class="refitem refitem-button" data-rule="'+RULES.indexOf(x)+'"><div class="refmeta">'+esc(x[0])+' · '+esc(x[2])+'</div><h3>'+esc(x[1])+'</h3><p>'+esc(x[3])+'</p>'+(x[4]?'<div class="example"><b>Exemplu:</b> '+esc(x[4])+'</div>':'')+'<div class="ref-open">Deschide explicația completă <span>＋</span></div></button>'}).join(""):'<p class="empty">Nu am găsit reguli pentru căutarea aceasta.</p>';
 document.querySelectorAll("#cats button").forEach(function(b){b.classList.toggle("on",b.dataset.cat===active)});
}
function openRule(index){
 var x=RULES[index]; if(!x)return;
 var modal=$("ruleModal");
 $("ruleModalTitle").textContent=x[1]; $("ruleModalMeta").textContent=x[0]+" · "+x[2];
 $("ruleModalBody").innerHTML='<section><h4>Regula pe scurt</h4><p>'+esc(x[3])+'</p></section>'+(x[4]?'<section><h4>Exemplu practic</h4><p>'+esc(x[4])+'</p></section>':'')+(x[5]?'<section><h4>Cum o aplici la masă</h4><p>'+esc(x[5])+'</p></section>':'<section><h4>Cum o aplici la masă</h4><p>Aplică textul regulii în ordinea indicată și verifică eligibilitatea, ținta și momentul declanșării înainte de a continua.</p></section>')+(x[6]?'<section class="rule-warning"><h4>Excepții și greșeli frecvente</h4><p>'+esc(x[6])+'</p></section>':'')+'<p class="rule-source">Sursă: Core Rules PDF atașat · '+esc(x[2])+'. Rezumat explicativ, nu înlocuiește textul oficial.</p>';
 modal.hidden=false; document.body.classList.add("modal-open"); $("ruleModalClose").focus();
}
function closeRule(){ $("ruleModal").hidden=true; document.body.classList.remove("modal-open"); }

App.start(function(){
 $("cats").innerHTML=cats.map(function(c){return '<button data-cat="'+esc(c)+'">'+esc(c)+'</button>'}).join("");
 $("cats").addEventListener("click",function(e){var b=e.target.closest("button[data-cat]");if(b){active=b.dataset.cat;renderRules()}});
 $("q").addEventListener("input",renderRules);$("results").addEventListener("click",function(e){var b=e.target.closest("[data-rule]");if(b)openRule(Number(b.dataset.rule))});$("ruleModalClose").addEventListener("click",closeRule);$("ruleModal").addEventListener("click",function(e){if(e.target===$("ruleModal"))closeRule()});document.addEventListener("keydown",function(e){if(e.key==="Escape"&&!$("ruleModal").hidden)closeRule()});renderRules();
});
